body.script:
(function () {
    function markReady() {
        if (!(window.googlefc && typeof window.googlefc.showRevocationMessage === 'function')) {
            return false;
        }
        var el = document.getElementById('fcConsentRevocationWeb');
        if (!el) {
            return false;
        }
        el.classList.add('fc-ready');
        el.removeAttribute('hidden');
        return true;
    }

    function scheduleMarkRevocationReady() {
        if (markReady()) {
            return;
        }
        var tries = 0;
        var timer = setInterval(function () {
            tries++;
            if (markReady() || tries >= 50) {
                clearInterval(timer);
            }
        }, 200);
    }

    window.__fcScheduleMarkRevocationReady = scheduleMarkRevocationReady;

    function bindClick() {
        var el = document.getElementById('fcConsentRevocationWeb');
        if (!el || el.getAttribute('data-fc-bound')) {
            return;
        }
        el.setAttribute('data-fc-bound', '1');
        var btn = el.querySelector('button');
        if (!btn) {
            return;
        }
        btn.addEventListener('click', function (e) {
            e.preventDefault();
            if (window.googlefc && typeof window.googlefc.showRevocationMessage === 'function') {
                window.googlefc.showRevocationMessage();
                return;
            }
            window.googlefc = window.googlefc || {};
            window.googlefc.callbackQueue = window.googlefc.callbackQueue || [];
            window.googlefc.callbackQueue.push({
                CONSENT_API_READY: function () {
                    if (typeof window.googlefc.showRevocationMessage === 'function') {
                        window.googlefc.showRevocationMessage();
                    }
                }
            });
        });
    }

    function onReady() {
        bindClick();
        scheduleMarkRevocationReady();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', onReady);
    } else {
        onReady();
    }

    scheduleMarkRevocationReady();
    if (window.__fcConsentApiReady) {
        scheduleMarkRevocationReady();
    }
})();

